const fs = require('fs');

const INF = 1000000001;

class Pair {
    constructor(first, second) {
        this.first = first;
        this.second = second;
    }
}

function sort(arr) {
    function quickSort(leftBound, rightBound) {
        if (rightBound - leftBound + 1 < 2) {
            return;
        }

        let left = leftBound;
        const pivot = leftBound + Math.floor((rightBound - leftBound + 1) / 2);

        [arr[pivot], arr[rightBound]] = [arr[rightBound], arr[pivot]];

        for (let i = leftBound; i <= rightBound; i++) {
            if (arr[i] < arr[rightBound]) {
                [arr[i], arr[left]] = [arr[left], arr[i]];
                left++;
            }
        }

        [arr[left], arr[rightBound]] = [arr[rightBound], arr[left]];

        quickSort(leftBound, left - 1);
        quickSort(left + 1, rightBound);
    }

    quickSort(0, arr.length - 1);
    return arr;
}

function check(n) {
    let s = 0;
    while (n > 0) {
        s += n % 10;
        n = Math.floor(n / 10);
    }
    return s === 10;
}

function solution(input) {
    let k = Number(input.trim());

    for (let i = 19; k > 0; i++) {
        if (check(i)) {
            k--;
        }
        if (k === 0) {
            return String(i);
        }
    }

    return '';
}

const input = fs.readFileSync(0, 'utf8');
process.stdout.write(solution(input));

